-- Where each SRS card came from, so the daily new-card limit counts only what
-- the queue introduced. A finished lesson, a saved word or a missed Speak
-- prompt is the learner's own choice and must not use up — or be blocked by —
-- the day's quota. Plus an index for "how many new cards today".
--
-- Generated by drizzle-kit, then made idempotent by hand, and with a backfill
-- for the cards whose origin is certain from their kind: grammar topics only
-- ever enter review by finishing their lesson, and Speak prompts only by being
-- missed in a session. Everything else stays `queue`, which is right for
-- nearly all of it.

ALTER TABLE "srs_cards" ADD COLUMN IF NOT EXISTS "origin" text DEFAULT 'queue' NOT NULL;--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "srs_cards_first_seen_idx" ON "srs_cards" USING btree ("user_id","language_id","first_seen_at");--> statement-breakpoint
UPDATE "srs_cards" sc SET "origin" = CASE si.kind WHEN 'grammar' THEN 'lesson' ELSE 'speak-miss' END
FROM "study_item_facets" f
JOIN "study_items" si ON si.id = f.study_item_id
WHERE f.id = sc.facet_id
  AND si.kind IN ('grammar', 'speak')
  AND sc.origin = 'queue';
